def _completed_jobs(realpath: str | None, at: int) -> dict[str, dict[str, Any]]:
    # The completion records visible at ``at``, keyed by job id for the
    # capacity and migration consumers. A missing ledger leaves every
    # historical occupancy in place; an invalid ledger is a ValueError.
    if realpath is None:
        return {}
    records, _idempotency, _events, _raw = _load_standalone(realpath)
    return {record["job_id"]: record for record in records.values()
            if record["at"] <= at}


